#!/usr/bin/env python3
"""Install the high-fidelity Character Select correction after archive verification.

Applies reviewed source deltas to the expanded v0.8.4 Character Select builder/runtime:
- separate 256x192 character overlays with independent per-frame palettes;
- authentic lock Animate states and corrected grid/cursor alignment;
- XA stayFunky encoded as file 1/channel 0 for PSXFunkin's CD filter;
- robust authentic introSelect frame extraction.
No replacement artwork is created.
"""
from pathlib import Path
import base64, gzip, hashlib, py_compile, subprocess, sys, tempfile

if len(sys.argv) != 2:
    raise SystemExit("usage: fix_charselect_intro_extraction.py <builder.py>")

builder = Path(sys.argv[1])
runtime = builder.with_name("apply_v084_charselect_full.py")
if not builder.is_file() or not runtime.is_file():
    raise SystemExit("expanded Character Select scripts are missing")

EXPECTED_BEFORE_BUILD = "aefbdec3e9bb0d020a2e525d0fec6fdb5182445515245a622b92d37b8ed0f051"
EXPECTED_BEFORE_RUNTIME = "f36376bd0949f1f3d2b2a0ec31a9bebccd8a29df24aff82627c8f4ff5895097e"
EXPECTED_AFTER_BUILD = "3dccad884baddc9efbb50f99936fa12ffea6144c7cd9842a485f4fcdb5c4135f"
EXPECTED_AFTER_RUNTIME = "ab573331cec034f5276e5e5d6b2e05e5a0b83fe83b42408b9cf3e9a2a48eec58"

BUILD_PATCH = ""
RUNTIME_PATCH = ""

def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()

def apply_patch(path: Path, payload: str) -> None:
    diff = gzip.decompress(base64.b64decode(payload))
    p = subprocess.run(["patch", "--batch", "--forward", str(path)], input=diff,
                       stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
    sys.stdout.buffer.write(p.stdout)
    if p.returncode != 0:
        raise SystemExit(f"failed to patch {path}")

if sha(builder) != EXPECTED_BEFORE_BUILD:
    raise SystemExit("unexpected expanded builder baseline")
if sha(runtime) != EXPECTED_BEFORE_RUNTIME:
    raise SystemExit("unexpected expanded runtime baseline")

apply_patch(builder, BUILD_PATCH)
apply_patch(runtime, RUNTIME_PATCH)

if sha(builder) != EXPECTED_AFTER_BUILD:
    raise SystemExit("high-fidelity builder hash mismatch after patch")
if sha(runtime) != EXPECTED_AFTER_RUNTIME:
    raise SystemExit("high-fidelity runtime hash mismatch after patch")

py_compile.compile(str(builder), doraise=True)
py_compile.compile(str(runtime), doraise=True)
print("installed high-fidelity Character Select correction")
print("builder sha256=" + EXPECTED_AFTER_BUILD)
print("runtime sha256=" + EXPECTED_AFTER_RUNTIME)
